package com.profa.security;import com.profa.user.User;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.util.*;@Service public class JwtService{@Value("${app.jwt.secret}")String secret;@Value("${app.jwt.expiration-ms:3600000}")long expiration;private SecretKey key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));}public String generate(User u){return Jwts.builder().subject(u.getId().toString()).claim("role",u.getRole().name()).claim("email",u.getEmail()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiration)).signWith(key()).compact();}public Jws<Claims> parse(String token){return Jwts.parser().verifyWith(key()).build().parseSignedClaims(token);}}